// Prepare Turn: reads the register_message result and decides the route for this message.
// Routes: answer (normal), limit (a message cap was reached), duplicate (WhatsApp redelivery).
const reg = $input.first().json;
const input = $('Config').first().json;
const settings = reg.settings || {};

const num = (key, fallback) => {
  const v = parseFloat(settings[key]);
  return Number.isFinite(v) ? v : fallback;
};

let route = 'answer';
if (reg.duplicate) route = 'duplicate';
else if (!reg.allowed) route = 'limit';

return [{
  json: {
    route,
    limit_reason: reg.limit_reason || null,
    input: {
      channel: input.channel,
      session_id: input.session_id,
      text: String(input.text || '').trim().slice(0, 2000),
      is_test: !!input.is_test,
      dry_run: !!input.dry_run,
      phone_number_id: input.phone_number_id || null,
    },
    settings,
    num: {
      top_k: num('top_k', 4),
      max_sources: num('max_sources', 5),
      min_similarity: num('min_similarity', 0.3),
      max_output_tokens: num('max_output_tokens', 1200),
      max_contact_asks: num('max_contact_asks', 2),
    },
    conversation: reg.conversation || {},
    history: Array.isArray(reg.history) ? reg.history : [],
    previous_user_message: reg.previous_user_message || null,
  },
}];

// Search Queries: one search for the message itself, and one that adds the previous customer
// message so follow-ups like "does it include weekends?" still find the right article.
// Each item carries the embedding request for Gemini's embedContent endpoint.
const p = $('Prepare Turn').first().json;
const S = p.settings;
const dims = parseInt(S.embedding_dimensions, 10) || 1536;
const text = p.input.text;

const item = (query, kind) => ({
  json: {
    query,
    kind,
    embed_body: {
      content: { parts: [{ text: query }] },
      taskType: 'RETRIEVAL_QUERY',
      outputDimensionality: dims,
    },
  },
});

const queries = [item(text, 'message')];
const prev = (p.previous_user_message || '').trim();
if (prev && prev !== text) {
  queries.push(item(`${prev.slice(0, 500)}\n${text}`, 'with_previous'));
}
return queries;

// Merge Sources: combines both searches, keeps the best score per chunk, labels the top chunks
// S1..Sn and builds the model request. The provider setting picks the request shape:
// gemini (generateContent with a response schema) or openai (Responses API with a JSON schema).
const p = $('Prepare Turn').first().json;
const S = p.settings;
const N = p.num;
const SCHEMA = {"type": "object", "additionalProperties": false, "required": ["reply", "answer_status", "cited_sources", "wants_human", "declines_handoff", "frustration", "issue_type", "contact_name", "contact_email", "injection_detected"], "properties": {"reply": {"type": "string", "description": "The message to send to the customer."}, "answer_status": {"type": "string", "enum": ["answered", "not_in_kb", "clarify", "greeting", "off_topic", "contact_details"], "description": "answered = the reply answers from SOURCES; not_in_kb = SOURCES do not answer a support question."}, "cited_sources": {"type": "array", "items": {"type": "string"}, "description": "Labels of the SOURCES used in the reply, for example S1."}, "wants_human": {"type": "boolean"}, "declines_handoff": {"type": "boolean"}, "frustration": {"type": "string", "enum": ["none", "mild", "high"]}, "issue_type": {"type": "string", "enum": ["account_access", "security", "network_vpn", "email", "devices", "onboarding_offboarding", "backups", "billing", "plans_contract", "onsite", "other"]}, "contact_name": {"type": ["string", "null"]}, "contact_email": {"type": ["string", "null"]}, "injection_detected": {"type": "boolean"}}};
const GEMINI_SCHEMA = {"type": "object", "required": ["reply", "answer_status", "cited_sources", "wants_human", "declines_handoff", "frustration", "issue_type", "contact_name", "contact_email", "injection_detected"], "properties": {"reply": {"type": "string", "description": "The message to send to the customer."}, "answer_status": {"type": "string", "enum": ["answered", "not_in_kb", "clarify", "greeting", "off_topic", "contact_details"], "description": "answered = the reply answers from SOURCES; not_in_kb = SOURCES do not answer a support question."}, "cited_sources": {"type": "array", "items": {"type": "string"}, "description": "Labels of the SOURCES used in the reply, for example S1."}, "wants_human": {"type": "boolean"}, "declines_handoff": {"type": "boolean"}, "frustration": {"type": "string", "enum": ["none", "mild", "high"]}, "issue_type": {"type": "string", "enum": ["account_access", "security", "network_vpn", "email", "devices", "onboarding_offboarding", "backups", "billing", "plans_contract", "onsite", "other"]}, "contact_name": {"type": "string", "nullable": true}, "contact_email": {"type": "string", "nullable": true}, "injection_detected": {"type": "boolean"}}};

// Rows come from the match_documents function: { id, content, metadata, similarity }.
const rows = $input.all()
  .map((i) => i.json)
  .filter((j) => j && typeof j.content === 'string' && j.content.length);

// match_documents returns its top matches whenever the knowledge base has content, so no rows at all
// means the knowledge base is empty. The next node routes this to the fallback reply and an alert.
if (!rows.length) {
  return [{ json: { search_failed: true, error: { message: 'Knowledge base search returned no rows: the knowledge base is empty or the search failed.' } } }];
}

const best = new Map();
for (const r of rows) {
  const md = r.metadata || {};
  const key = `${md.file_id || md.title || ''}|${r.content.slice(0, 200)}`;
  const seen = best.get(key);
  if (!seen || (r.similarity ?? 0) > (seen.similarity ?? 0)) best.set(key, r);
}

const top = [...best.values()]
  .sort((a, b) => (b.similarity ?? 0) - (a.similarity ?? 0))
  .slice(0, N.max_sources);

const sources = top.map((r, i) => {
  const md = r.metadata || {};
  return {
    label: `S${i + 1}`,
    title: md.title || 'Help article',
    file_id: md.file_id || null,
    url: md.url || null,
    score: Math.round((r.similarity ?? 0) * 1000) / 1000,
    text: r.content,
  };
});
const bestScore = sources.length ? sources[0].score : 0;

const sourcesBlock = sources.length
  ? sources.map((s) => `[${s.label}] ${s.title}\n${s.text}`).join('\n\n')
  : '(No help articles matched this message.)';

const stateText = {
  bot: 'normal conversation',
  collecting_contact: "waiting for the customer's name and email address so a person on the team can follow up",
  handed_off: 'this conversation has already been passed to a person on the team',
}[p.conversation.status] || 'normal conversation';

const today = new Date().toISOString().slice(0, 10);
const system = String(S.system_prompt || '')
  .split('{{state}}').join(stateText)
  .split('{{today}}').join(today)
  .split('{{channel}}').join(p.input.channel === 'whatsapp' ? 'WhatsApp' : 'website chat');
const sourcesMessage = `SOURCES (the only facts you may use):\n\n${sourcesBlock}`;

const history = p.history
  .filter((h) => h && h.content)
  .map((h) => ({ role: h.role === 'assistant' ? 'assistant' : 'user', content: String(h.content).slice(0, 1500) }));

const provider = String(S.provider || 'gemini').toLowerCase();
let body;
if (provider === 'openai') {
  body = {
    model: S.model,
    input: [
      { role: 'system', content: system },
      { role: 'system', content: sourcesMessage },
      ...history,
      { role: 'user', content: p.input.text },
    ],
    max_output_tokens: N.max_output_tokens,
    text: { format: { type: 'json_schema', name: 'support_reply', strict: true, schema: SCHEMA } },
  };
  if (S.reasoning_effort) body.reasoning = { effort: S.reasoning_effort };
} else {
  // Gemini wants alternating user and model turns that start with the user.
  const contents = [];
  for (const h of history) {
    const role = h.role === 'assistant' ? 'model' : 'user';
    if (!contents.length && role === 'model') continue;
    const last = contents[contents.length - 1];
    if (last && last.role === role) last.parts[0].text += `\n${h.content}`;
    else contents.push({ role, parts: [{ text: h.content }] });
  }
  const last = contents[contents.length - 1];
  if (last && last.role === 'user') last.parts[0].text += `\n${p.input.text}`;
  else contents.push({ role: 'user', parts: [{ text: p.input.text }] });
  body = {
    systemInstruction: { parts: [{ text: `${system}\n\n${sourcesMessage}` }] },
    contents,
    generationConfig: {
      temperature: 0,
      maxOutputTokens: N.max_output_tokens,
      responseMimeType: 'application/json',
      responseSchema: GEMINI_SCHEMA,
    },
  };
}

return [{
  json: {
    search_failed: false,
    provider,
    model: S.model,
    request_body: body,
    sources: sources.map(({ text, ...rest }) => rest),
    sources_text: Object.fromEntries(sources.map((s) => [s.label, s.text])),
    best_score: bestScore,
  },
}];

// Apply Rules: reads the model's JSON, checks that an answer is grounded in the retrieved
// articles, applies the escalation rules from bot_settings and writes the final reply.
// The model suggests; this node decides. Handoff replies come from editable templates.
const p = $('Prepare Turn').first().json;
const ms = $('Merge Sources').first().json;
const res = $input.first().json;
const S = p.settings;
const N = p.num;
const conv = p.conversation || {};
const channel = p.input.channel;
const text = p.input.text;
const flags = {};

// ---------- 1. Read the model output (Gemini or OpenAI) ----------
function outputText(r) {
  if (Array.isArray(r.candidates)) {
    const cand = r.candidates[0] || {};
    if (cand.finishReason && cand.finishReason !== 'STOP') flags.incomplete = cand.finishReason;
    if (r.promptFeedback && r.promptFeedback.blockReason) flags.blocked = r.promptFeedback.blockReason;
    const parts = (cand.content && cand.content.parts) || [];
    const texts = parts.filter((c) => typeof c.text === 'string' && !c.thought).map((c) => c.text);
    return texts.length ? texts.join('') : null;
  }
  if (typeof r.output_text === 'string') return r.output_text;
  for (const item of r.output || []) {
    if (item.type !== 'message') continue;
    for (const c of item.content || []) {
      if (c.type === 'output_text' && typeof c.text === 'string') return c.text;
      if (c.type === 'refusal') flags.model_refusal = String(c.refusal || '').slice(0, 200);
    }
  }
  return null;
}

const EMPTY = {
  reply: '', answer_status: 'not_in_kb', cited_sources: [], wants_human: false, declines_handoff: false,
  frustration: 'none', issue_type: 'other', contact_name: null, contact_email: null, injection_detected: false,
};
let m = null;
const raw = outputText(res);
try {
  m = raw ? JSON.parse(raw) : null;
} catch (e) {
  flags.parse_error = String(e.message).slice(0, 200);
}
if (!m || typeof m !== 'object') {
  flags.unreadable = true;
  m = { ...EMPTY };
}
if (res.status === 'incomplete') flags.incomplete = (res.incomplete_details && res.incomplete_details.reason) || 'incomplete';
m.reply = String(m.reply || '').trim();

// ---------- 2. Grounding check ----------
const labels = ms.sources.map((s) => s.label);
const citedRaw = Array.isArray(m.cited_sources) ? m.cited_sources : [];
const cited = [...new Set(citedRaw.filter((l) => labels.includes(l)))];
const badCites = citedRaw.filter((l) => !labels.includes(l));
let status = m.answer_status;

if (status === 'answered') {
  if (!cited.length) flags.no_citation = true;
  if (badCites.length) flags.invalid_citation = badCites;
  if (ms.best_score < N.min_similarity) flags.low_similarity = ms.best_score;
  if (flags.no_citation || flags.invalid_citation || flags.low_similarity !== undefined) {
    status = 'not_in_kb';
    flags.grounding_override = true;
  }
}

// Numbers in an answer should appear in the cited articles (or in the customer's own message).
const numberMode = String(S.number_check || 'flag').toLowerCase();
if (status === 'answered' && numberMode !== 'off') {
  const numbersIn = (s) => new Set((String(s).replace(/(\d),(\d{3})/g, '$1$2').match(/\d+(?:\.\d+)?/g)) || []);
  const allowed = numbersIn(cited.map((l) => ms.sources_text[l] || '').join(' ') + ' ' + text);
  const replyNoLists = m.reply.replace(/^\s*\d+[.)]\s/gm, '');
  const unsupported = [...numbersIn(replyNoLists)].filter((n) => !allowed.has(n));
  if (unsupported.length) {
    flags.unsupported_numbers = unsupported;
    if (numberMode === 'block') {
      status = 'not_in_kb';
      flags.grounding_override = true;
    }
  }
}
if (status === 'not_in_kb') flags.not_sure = true;

// ---------- 3. Escalation signals ----------
const lower = text.toLowerCase();
const escapeRe = (s) => s.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
const keywords = String(S.handoff_keywords || '').split(',').map((s) => s.trim().toLowerCase()).filter(Boolean);
const keywordHit = keywords.find((k) => new RegExp(`(^|[^a-z])${escapeRe(k)}([^a-z]|$)`).test(lower)) || null;

const injection = !!m.injection_detected;
if (injection) flags.injection = true;

const askedRule = String(S.escalate_when_asked || 'yes').toLowerCase() === 'yes';
const keywordCounts = keywordHit && (status !== 'answered' || text.length < 80);
const wantsHuman = askedRule && !injection && (m.wants_human === true || !!keywordCounts);
if (keywordCounts && m.wants_human !== true) flags.keyword_handoff = keywordHit;

const rank = { none: 0, mild: 1, high: 2 };
const frustrationRule = String(S.escalate_when_frustrated || 'high').toLowerCase();
const threshold = frustrationRule in rank ? rank[frustrationRule] : 99;
const frustrated = !injection && threshold > 0 && threshold < 99 && (rank[m.frustration] || 0) >= threshold;

const outsideRule = String(S.escalate_when_not_in_kb || 'yes').toLowerCase() === 'yes';
const outside = status === 'not_in_kb' && outsideRule && !injection;

let reason = wantsHuman ? 'asked_for_person' : frustrated ? 'frustrated' : outside ? 'outside_kb' : null;

// ---------- 4. Contact details (only if the customer actually wrote them) ----------
const customerText = [text, ...p.history.filter((h) => h.role === 'user').map((h) => String(h.content))]
  .join('\n').toLowerCase();
const emailRe = /[a-z0-9._%+-]+@[a-z0-9.-]+\.[a-z]{2,}/i;
const asEmail = (v) => {
  const hit = typeof v === 'string' ? v.match(emailRe) : null;
  const e = hit ? hit[0].toLowerCase() : null;
  return e && customerText.includes(e) ? e : null;
};
const newEmail = asEmail(m.contact_email) || asEmail(text);
const email = newEmail || conv.contact_email || null;

let newName = null;
if (typeof m.contact_name === 'string' && m.contact_name.trim()) {
  const candidate = m.contact_name.trim().slice(0, 80);
  if (customerText.includes(candidate.toLowerCase().split(' ')[0])) newName = candidate;
}
const name = newName || conv.contact_name || null;
const phone = conv.contact_phone || null;
const reachable = !!email || (channel === 'whatsapp' && !!phone);

// ---------- 5. Decide the reply and the action ----------
const fill = (t) => String(t || '').split('{{email}}').join(email || '').split('{{name}}').join(name || '');
const prefixFor = (r) => (r === 'frustrated' ? S.prefix_frustrated || '' : r === 'outside_kb' ? S.prefix_outside_kb || '' : '');
const firstName = name ? String(name).split(' ')[0] : null;
const thanks = firstName ? `Thanks, ${firstName}. ` : 'Thanks. ';
const handoffText = () => (email
  ? fill(S.handoff_email_text)
  : channel === 'whatsapp' && phone ? fill(S.handoff_phone_text) : fill(S.handoff_no_contact_text));
const answerPart = status === 'answered' && m.reply ? `${m.reply} ` : '';

let reply = m.reply;
let action = 'none';
const state = {};
const current = conv.status || 'bot';
const pending = conv.pending_reason || null;
const asks = conv.contact_asks || 0;

if (current === 'handed_off') {
  if (reason) {
    action = 'handoff_followup';
    reply = answerPart + (reason === 'outside_kb' ? prefixFor(reason) : '') + fill(S.already_handed_off_text);
  } else if (status === 'not_in_kb') {
    reply = fill(S.not_sure_text);
  }
} else if (current === 'collecting_contact') {
  if (m.declines_handoff === true && !wantsHuman) {
    reply = fill(S.declined_text);
    state.status = 'bot';
    state.pending_reason = null;
    state.contact_asks = 0;
    reason = null;
  } else if (reachable) {
    action = 'handoff_now';
    reason = pending || reason || 'asked_for_person';
    reply = (newEmail ? thanks : '') + answerPart + handoffText();
  } else if (asks >= N.max_contact_asks) {
    action = 'handoff_now';
    reason = pending || reason || 'asked_for_person';
    reply = answerPart + fill(S.handoff_no_contact_text);
  } else {
    state.contact_asks = asks + 1;
    reply = answerPart + fill(S.reask_email_text);
    reason = null;
  }
} else if (reason) {
  if (reachable) {
    action = 'handoff_now';
    reply = (newEmail && firstName ? thanks : '') + answerPart + prefixFor(reason) + handoffText();
  } else {
    action = 'ask_contact';
    state.status = 'collecting_contact';
    state.pending_reason = reason;
    state.contact_asks = 1;
    reply = answerPart + prefixFor(reason) + fill(S.ask_contact_text);
  }
} else if (status === 'not_in_kb') {
  reply = fill(S.not_sure_text);
}

if (!reply) reply = fill(S.not_sure_text);

// ---------- 6. Conversation changes for log_reply ----------
if (newEmail) state.contact_email = newEmail;
if (newName) state.contact_name = newName;
if (m.issue_type && m.issue_type !== 'other') state.issue_type = m.issue_type;
else if (!conv.issue_type && m.issue_type) state.issue_type = 'other';
if (status === 'not_in_kb') state.not_sure_inc = 1;

const usage = res.usage || (res.usageMetadata
  ? { input_tokens: res.usageMetadata.promptTokenCount, output_tokens: res.usageMetadata.candidatesTokenCount }
  : {});
return [{
  json: {
    session_id: p.input.session_id,
    channel,
    is_test: p.input.is_test,
    dry_run: p.input.dry_run,
    phone_number_id: p.input.phone_number_id,
    reply: reply.replace(/\s+\n/g, '\n').trim(),
    answer_status: status,
    model_answer_status: m.answer_status,
    action,
    reason: action === 'none' ? null : reason,
    state,
    flags,
    retrieved: ms.sources,
    cited,
    best_score: ms.best_score,
    model: res.model || res.modelVersion || S.model || null,
    prompt_version: S.prompt_version || null,
    tokens_in: usage.input_tokens ?? null,
    tokens_out: usage.output_tokens ?? null,
    latency_ms: Date.now() - Number($('Config').first().json.started_ms || Date.now()),
    contact: { name, email, phone },
    issue_type: state.issue_type || conv.issue_type || null,
    frustration: m.frustration || 'none',
    latest_text: text,
    delivery: {
      slack_channel: S.slack_channel || null,
      team_email: S.team_email || null,
      from_email: S.from_email || null,
      sheet_id: S.sheet_id || null,
    },
  },
}];

// Skip Duplicate: WhatsApp delivered the same message twice; nothing is sent the second time.
const p = $('Prepare Turn').first().json;
return [{ json: { output: '', reply: '', skip: true, session_id: p.input.session_id, answer_status: 'duplicate', action: 'none' } }];

// Fallback Reply: the knowledge base search or the model call failed after its retries.
// The customer gets a polite reply, the turn is logged, and the team is alerted.
const p = $('Prepare Turn').first().json;
const S = p.settings;
const conv = p.conversation || {};
const err = $input.first().json || {};
const message = (err.error && (err.error.message || err.error.description)) || err.message || 'Unknown error';
const failedNode = $('Ask Model').isExecuted ? 'Ask Model'
  : $('Search Knowledge Base').isExecuted ? 'Search Knowledge Base'
  : $('Embed Query').isExecuted ? 'Embed Query' : 'Search Queries';
const cfg = $('Config').first().json;

return [{
  json: {
    session_id: p.input.session_id,
    channel: p.input.channel,
    is_test: p.input.is_test,
    dry_run: p.input.dry_run,
    phone_number_id: p.input.phone_number_id,
    reply: S.fallback_text || 'Sorry, I am having trouble answering right now. Please try again in a few minutes.',
    answer_status: 'error',
    model_answer_status: null,
    action: 'none',
    reason: null,
    state: {},
    flags: { error: String(message).slice(0, 500), failed_node: failedNode },
    retrieved: [],
    cited: [],
    best_score: null,
    model: S.model || null,
    prompt_version: S.prompt_version || null,
    tokens_in: null,
    tokens_out: null,
    latency_ms: Date.now() - Number(cfg.started_ms || Date.now()),
    contact: { name: conv.contact_name || null, email: conv.contact_email || null, phone: conv.contact_phone || null },
    issue_type: conv.issue_type || null,
    frustration: 'none',
    latest_text: p.input.text,
    delivery: {
      slack_channel: S.slack_channel || null,
      team_email: S.team_email || null,
      from_email: S.from_email || null,
      sheet_id: S.sheet_id || null,
    },
    alert: {
      workflow: '20 - Answer Message',
      node: failedNode,
      message: String(message).slice(0, 500),
      session_id: p.input.session_id,
      is_test: p.input.is_test,
      execution_url: `${cfg.n8n_url}/workflow/${$workflow.id}/executions/${$execution.id}`,
    },
  },
}];

// Reply Data: picks the reply from whichever path produced it (answer, message cap or fallback).
for (const name of ['Apply Rules', 'Limit Reply', 'Fallback Reply']) {
  if ($(name).isExecuted) return [{ json: $(name).first().json }];
}
throw new Error('No reply was produced for this message');

// Escalation Input: what 30 - Escalate to Team needs to hand the chat to a person.
const r = $('Reply Data').first().json;
return [{
  json: {
    session_id: r.session_id,
    channel: r.channel,
    action: r.action,
    reason: r.reason,
    latest_text: r.latest_text,
    reply: r.reply,
    contact: r.contact,
    issue_type: r.issue_type,
    dry_run: !!r.dry_run,
    slack_channel: r.delivery.slack_channel,
    team_email: r.delivery.team_email,
    from_email: r.delivery.from_email,
  },
}];

// Log Row: one row per conversation in the Google Sheets log, updated after every reply.
// Column names match the header row of the "conversations" tab.
const r = $('Reply Data').first().json;
const logged = $('Log Reply').first().json || {};
const c = logged.conversation || {};
const esc = $('Escalate').isExecuted ? $('Escalate').first().json : null;

let status = c.status || (r.state && r.state.status) || 'bot';
if (esc && esc.claimed) status = 'handed_off';

const maskPhone = (ph) => (ph ? `${String(ph).slice(0, 2)}****${String(ph).slice(-4)}` : '');
const iso = (t) => (t ? new Date(t).toISOString().replace('T', ' ').slice(0, 19) : '');

return [{
  json: {
    session_id: r.session_id,
    started_at: iso(c.started_at),
    last_message_at: iso(c.last_message_at || Date.now()),
    channel: r.channel,
    status,
    handoff_reason: (esc && esc.claimed ? r.reason : c.handoff_reason) || '',
    name: c.contact_name || (r.contact && r.contact.name) || '',
    email: c.contact_email || (r.contact && r.contact.email) || '',
    phone: maskPhone(c.contact_phone),
    issue_type: c.issue_type || r.issue_type || '',
    messages: c.message_count || '',
    not_sure_count: c.not_sure_count ?? '',
    first_question: c.first_question || '',
    last_answer_status: r.answer_status || '',
    transcript: logged.transcript_text || '',
  },
}];

// Return Reply: the result handed back to the channel workflow (and to the test runner).
const r = $('Reply Data').first().json;
const logged = $('Log Reply').isExecuted ? $('Log Reply').first().json || {} : {};
const c = logged.conversation || {};
const esc = $('Escalate').isExecuted ? $('Escalate').first().json : null;

let status = c.status || (r.state && r.state.status) || null;
if (esc && esc.claimed) status = 'handed_off';
if (logged.error) r.flags.log_error = String(logged.error.message || logged.error).slice(0, 300);

return [{
  json: {
    output: r.reply,
    reply: r.reply,
    skip: false,
    session_id: r.session_id,
    phone_number_id: r.phone_number_id || null,
    answer_status: r.answer_status,
    model_answer_status: r.model_answer_status,
    action: r.action,
    reason: r.reason,
    status,
    cited: r.cited || [],
    cited_titles: (r.retrieved || []).filter((s) => (r.cited || []).includes(s.label)).map((s) => s.title),
    sources: (r.retrieved || []).map((s) => ({ label: s.label, title: s.title, score: s.score })),
    best_score: r.best_score,
    flags: r.flags || {},
    contact: r.contact,
    issue_type: r.issue_type,
    frustration: r.frustration,
    escalation: esc
      ? {
        claimed: esc.claimed ?? null,
        sent_slack: esc.sent_slack ?? null,
        sent_email: esc.sent_email ?? null,
        dry_run: esc.dry_run ?? null,
        transcript_lines: esc.transcript_lines ?? null,
        transcript_text: esc.transcript_text ? String(esc.transcript_text).slice(0, 4000) : null,
        followup: esc.followup ?? null,
      }
      : null,
    model: r.model,
    prompt_version: r.prompt_version,
    tokens_in: r.tokens_in,
    tokens_out: r.tokens_out,
    latency_ms: r.latency_ms,
  },
}];

// Store Down Reply: Supabase could not be reached, so there are no settings and nothing can be
// logged. The customer still gets a reply and the team is alerted.
const cfg = $('Config').first().json;
const err = $input.first().json || {};
const message = (err.error && (err.error.message || err.error.description)) || err.message || 'Unknown error';
return [{
  json: {
    output: cfg.store_down_text,
    reply: cfg.store_down_text,
    skip: false,
    answer_status: 'error',
    action: 'none',
    reason: null,
    status: null,
    cited: [],
    sources: [],
    best_score: null,
    flags: { error: String(message).slice(0, 500), failed_node: 'Register Message' },
    session_id: cfg.session_id,
    phone_number_id: cfg.phone_number_id || null,
    alert: {
      workflow: '20 - Answer Message',
      node: 'Register Message',
      message: String(message).slice(0, 500),
      session_id: cfg.session_id,
      is_test: !!cfg.is_test,
      execution_url: `${cfg.n8n_url}/workflow/${$workflow.id}/executions/${$execution.id}`,
    },
  },
}];
